macro_rules! deps {
    () => {
        NavigationTarget!();
        HighlightedRange!();
    };
}

macro_rules! highlight_references {
    () => {
        deps!();
        fn highlight_references (sema : & Semantics < '_ , RootDatabase > , token : SyntaxToken , FilePosition { file_id , offset } : FilePosition ,) -> Option < Vec < HighlightedRange > > { let defs = if let Some ((range , _ , _ , resolution)) = sema . check_for_format_args_template (token . clone () , offset) { match resolution . map (Definition :: from) { Some (def) => iter :: once (def) . collect () , None => { return Some (vec ! [HighlightedRange { range , category : ReferenceCategory :: empty () , }]) ; } } } else { find_defs (sema , token . clone ()) } ; let usages = defs . iter () . filter_map (| & d | { d . usages (sema) . in_scope (& SearchScope :: single_file (file_id)) . include_self_refs () . all () . references . remove (& file_id) }) . flatten () . map (| FileReference { category , range , .. } | HighlightedRange { range , category }) ; let mut res = FxHashSet :: default () ; for & def in & defs { if let Definition :: Trait (t) = def { let trait_item_use_scope = (| | { let name_ref = token . parent () . and_then (ast :: NameRef :: cast) ? ; let path = full_path_of_name_ref (& name_ref) ? ; let parent = path . syntax () . parent () ? ; match_ast ! { match parent { ast :: UseTree (it) => it . syntax () . ancestors () . find (| it | { ast :: SourceFile :: can_cast (it . kind ()) || ast :: Module :: can_cast (it . kind ()) }) . zip (Some (true)) , ast :: PathType (it) => it . syntax () . ancestors () . nth (2) . and_then (ast :: TypeBoundList :: cast) ? . syntax () . parent () . filter (| it | ast :: WhereClause :: can_cast (it . kind ()) || ast :: TypeParam :: can_cast (it . kind ())) ? . ancestors () . find (| it | { ast :: Item :: can_cast (it . kind ()) }) . zip (Some (false)) , _ => None , } } }) () ; if let Some ((trait_item_use_scope , use_tree)) = trait_item_use_scope { res . extend (if use_tree { t . items (sema . db) } else { t . items_with_supertraits (sema . db) } . into_iter () . filter_map (| item | { Definition :: from (item) . usages (sema) . set_scope (Some (& SearchScope :: file_range (FileRange { file_id , range : trait_item_use_scope . text_range () , }))) . include_self_refs () . all () . references . remove (& file_id) }) . flatten () . map (| FileReference { category , range , .. } | HighlightedRange { range , category , }) ,) ; } } if matches ! (def , Definition :: Label (_)) { let label = token . parent_ancestors () . nth (1) . and_then (ast :: Label :: cast) ; if let Some (block) = label . and_then (| label | label . syntax () . parent ()) . and_then (ast :: BlockExpr :: cast) { for_each_tail_expr (& block . into () , & mut | tail | { if ! matches ! (tail , ast :: Expr :: BreakExpr (_)) { res . insert (HighlightedRange { range : tail . syntax () . text_range () , category : ReferenceCategory :: empty () , }) ; } }) ; } } match def { Definition :: Local (local) => { let category = if local . is_mut (sema . db) { ReferenceCategory :: WRITE } else { ReferenceCategory :: empty () } ; local . sources (sema . db) . into_iter () . flat_map (| x | x . to_nav (sema . db)) . filter (| decl | decl . file_id == file_id . file_id (sema . db)) . filter_map (| decl | decl . focus_range) . map (| range | HighlightedRange { range , category }) . for_each (| x | { res . insert (x) ; }) ; } def => { let navs = match def { Definition :: Module (module) => { NavigationTarget :: from_module_to_decl (sema . db , module) } def => match def . try_to_nav (sema) { Some (it) => it , None => continue , } , } ; for nav in navs { if nav . file_id != file_id . file_id (sema . db) { continue ; } let hl_range = nav . focus_range . map (| range | { let category = if matches ! (def , Definition :: Local (l) if l . is_mut (sema . db)) { ReferenceCategory :: WRITE } else { ReferenceCategory :: empty () } ; HighlightedRange { range , category } }) ; if let Some (hl_range) = hl_range { res . insert (hl_range) ; } } } } } res . extend (usages) ; if res . is_empty () { None } else { Some (res . into_iter () . collect ()) } }
    };
}

highlight_references!()